WITH latest AS (SELECT * FROM (SELECT *, ROW_NUMBER() OVER (PARTITION BY account_id, merchant ORDER BY txn_time, id) AS dedup_rank FROM transactions) ranked WHERE dedup_rank = 1), with_windows AS (SELECT id, account_id, txn_type, amount, txn_time, merchant, is_flagged, dedup_rank, AVG(amount) OVER (PARTITION BY merchant, txn_type ORDER BY CAST(txn_time AS BIGINT) RANGE BETWEEN 604800 PRECEDING AND CURRENT ROW) AS amount_avg_7d, ROW_NUMBER() OVER (PARTITION BY account_id ORDER BY amount, id) AS seq_no, RANK() OVER w_grp AS amount_rank FROM latest WINDOW w_grp AS (ORDER BY amount DESC NULLS LAST)), scored AS (SELECT *, COUNT(seq_no) OVER (PARTITION BY merchant ORDER BY CAST(txn_time AS BIGINT) RANGE BETWEEN 2592000 PRECEDING AND CURRENT ROW) AS seq_no_count_30d, MAX(seq_no) OVER (PARTITION BY merchant) AS merchant_max_seq_no FROM with_windows), filtered AS (SELECT *, CAST(seq_no_count_30d AS STRING) AS seq_no_count_30d_str FROM scored WHERE txn_time >= TIMESTAMP '2023-07-09 21:00:00' AND merchant IS NOT NULL) SELECT id, txn_type, amount, txn_time, dedup_rank, amount_avg_7d, seq_no, amount_rank, merchant_max_seq_no FROM filtered;
